 `ginfer_qwen3_6_35b_a3b_dflash_round_bench` drives the production Program through consecutive
diff --git a/bench/targets/qwen3_6_27b/dflash2_round_bench.cpp b/bench/targets/qwen3_6_27b/dflash2_round_bench.cpp
new file mode 100644
index 00000000..cca3a70e
--- /dev/null
+++ b/bench/targets/qwen3_6_27b/dflash2_round_bench.cpp
@@ -0,0 +1,405 @@
+#include <ginfer/targets/qwen3_6_27b/package.h>
+
+#include "artifact/binder.h"
+#include "artifact/materializer.h"
+#include "artifact/reader.h"
+#include "core/device.h"
+#include "runtime/engine/kv_capacity.h"
+#include "runtime/engine/request_memory.h"
+
+#include <cuda_profiler_api.h>
+
+#include <algorithm>
+#include <array>
+#include <chrono>
+#include <cstddef>
+#include <cstdint>
+#include <cstdlib>
+#include <filesystem>
+#include <fstream>
+#include <iostream>
+#include <limits>
+#include <numeric>
+#include <span>
+#include <stdexcept>
+#include <string>
+#include <string_view>
+#include <utility>
+#include <vector>
+
+namespace {
+
+namespace target = ginfer::targets::qwen3_6_27b;
+using Clock      = std::chrono::steady_clock;
+
+constexpr std::uint32_t kNativeContext       = 131072;
+constexpr std::uint32_t kDraftTokens         = 4;
+constexpr std::uint32_t kVerificationTokens  = 15;
+constexpr std::uint32_t kMaximumRoundOutputs = kVerificationTokens + 1;
+
+struct Options {
+    std::filesystem::path artifact = "out/qwen3_8_27b_nvfp4_dflash2_q4.ginfer";
+    std::filesystem::path corpus   = "bench/fixtures/bench_corpus.ids";
+    int device                     = 0;
+    int warmup                     = 5;
+    int repetitions                = 31;
+    std::uint32_t context_tokens   = 8192;
+    std::uint32_t batch_size       = 1;
+    bool use_cuda_graph            = true;
+    bool profile_measured          = false;
+};
+
+void print_usage(const char* executable) {
+    std::cout << "usage: " << executable
+              << " [--artifact <model.ginfer>] [--corpus <token-ids>] [--device <id>]"
+                 " [--context <tokens>] [--warmup <n>] [--reps <n>] [--batch <1..8>]"
+                 " [--no-cuda-graph] [--profile-measured]\n";
+}
+
+std::uint32_t parse_u32(const char* text, const char* label) {
+    std::size_t consumed      = 0;
+    const unsigned long value = std::stoul(text, &consumed);
+    if (text[consumed] != '\0' || value > std::numeric_limits<std::uint32_t>::max()) {
+        throw std::invalid_argument(std::string(label) + " is not a uint32");
+    }
+    return static_cast<std::uint32_t>(value);
+}
+
+Options parse_options(int argc, char** argv) {
+    Options options;
+    for (int index = 1; index < argc; ++index) {
+        const std::string_view argument(argv[index]);
+        const auto value = [&](const char* name) -> const char* {
+            if (++index >= argc) {
+                throw std::invalid_argument(std::string(name) + " needs value");
+            }
+            return argv[index];
+        };
+        if (argument == "--artifact") {
+            options.artifact = value("--artifact");
+        } else if (argument == "--corpus") {
+            options.corpus = value("--corpus");
+        } else if (argument == "--device") {
+            options.device = std::stoi(value("--device"));
+        } else if (argument == "--context") {
+            options.context_tokens = parse_u32(value("--context"), "context");
+        } else if (argument == "--warmup") {
+            options.warmup = std::stoi(value("--warmup"));
+        } else if (argument == "--reps") {
+            options.repetitions = std::stoi(value("--reps"));
+        } else if (argument == "--batch") {
+            options.batch_size = parse_u32(value("--batch"), "batch");
+        } else if (argument == "--no-cuda-graph") {
+            options.use_cuda_graph = false;
+        } else if (argument == "--profile-measured") {
+            options.profile_measured = true;
+        } else if (argument == "-h" || argument == "--help") {
+            print_usage(argc > 0 ? argv[0] : "ginfer_qwen3_8_27b_dflash2_round_bench");
+            std::exit(0);
+        } else {
+            throw std::invalid_argument("unknown argument: " + std::string(argument));
+        }
+    }
+    if (options.device < 0) { throw std::invalid_argument("--device must be nonnegative"); }
+    if (options.warmup < 1) {
+        throw std::invalid_argument("--warmup must be positive so measured rounds are steady");
+    }
+    if (options.repetitions <= 0) { throw std::invalid_argument("--reps must be positive"); }
+    if (options.profile_measured && options.repetitions != 1) {
+        throw std::invalid_argument("--profile-measured requires --reps 1");
+    }
+    if (options.context_tokens < 16 || options.context_tokens > kNativeContext) {
+        throw std::invalid_argument("--context must be in [16,131072]");
+    }
+    if (options.batch_size == 0 || options.batch_size > ginfer::kMaximumConcurrency) {
+        throw std::invalid_argument("--batch must be in [1,8]");
+    }
+    const std::uint64_t rounds =
+        static_cast<std::uint64_t>(options.warmup + options.repetitions);
+    const std::uint64_t request_extent =
+        static_cast<std::uint64_t>(options.context_tokens) + 1ULL +
+        rounds * static_cast<std::uint64_t>(kMaximumRoundOutputs);
+    if (request_extent > kNativeContext) {
+        throw std::invalid_argument("context and measured rounds exceed native capacity");
+    }
+    const std::uint64_t pages_per_request = (request_extent + 63ULL) / 64ULL;
+    if (pages_per_request * options.batch_size > kNativeContext / 64U) {
+        throw std::invalid_argument("batch request entitlements exceed shared KV capacity");
+    }
+    return options;
+}
+
+std::vector<ginfer::TokenId> load_corpus(const std::filesystem::path& path) {
+    std::ifstream input(path);
+    if (!input) { throw std::runtime_error("failed to open token corpus: " + path.string()); }
+    std::vector<ginfer::TokenId> tokens;
+    std::uint64_t value = 0;
+    while (input >> value) {
+        if (value > static_cast<std::uint64_t>(std::numeric_limits<ginfer::TokenId>::max())) {
+            throw std::invalid_argument("token corpus contains an out-of-range token id");
+        }
+        tokens.push_back(static_cast<ginfer::TokenId>(value));
+    }
+    if (tokens.empty()) { throw std::invalid_argument("token corpus is empty"); }
+    return tokens;
+}
+
+std::vector<ginfer::TokenId> prompt_tokens(std::span<const ginfer::TokenId> corpus,
+                                           std::uint32_t count, std::uint32_t lane) {
+    std::vector<ginfer::TokenId> prompt;
+    prompt.reserve(count);
+    const std::size_t offset = (static_cast<std::size_t>(lane) * 7919U) % corpus.size();
+    for (std::uint32_t index = 0; index < count; ++index) {
+        prompt.push_back(corpus[(offset + index) % corpus.size()]);
+    }
+    return prompt;
+}
+
+struct RoundMeasurement {
+    float gpu_ms                  = 0.0F;
+    double wall_ms                = 0.0;
+    std::uint32_t licensed_tokens = 0;
+};
+
+RoundMeasurement measure_round(target::Package::Program& program, ginfer::DeviceContext& device,
+                               std::uint32_t batch_size) {
+    std::array<std::uint32_t, ginfer::kMaximumConcurrency> lanes{};
+    std::array<ginfer::runtime::RoundBudget, ginfer::kMaximumConcurrency> budgets{};
+    for (std::uint32_t row = 0; row < batch_size; ++row) {
+        lanes[row]   = row;
+        budgets[row] = {.generated_tokens_remaining = kMaximumRoundOutputs};
+    }
+    const auto lane_span = std::span<const std::uint32_t>(lanes.data(), batch_size);
+    const auto budget_span =
+        std::span<const ginfer::runtime::RoundBudget>(budgets.data(), batch_size);
+
+    ginfer::CudaEventTimer timer(device);
+    const auto wall_start = Clock::now();
+    timer.start();
+    const auto round = program.decode_batch(lane_span, budget_span);
+    if (round.row_counts.size() != batch_size ||
+        (round.row_stride != kDraftTokens + 1U && round.row_stride != kMaximumRoundOutputs)) {
+        throw std::runtime_error("Qwen DFlash2 benchmark round returned invalid row metadata");
+    }
+
+    std::array<std::uint32_t, ginfer::kMaximumConcurrency> accepted{};
+    std::array<std::uint8_t, ginfer::kMaximumConcurrency> terminal{};
+    std::array<std::uint8_t, ginfer::kMaximumConcurrency> cancelled{};
+    std::uint32_t licensed = 0;
+    for (std::uint32_t row = 0; row < batch_size; ++row) {
+        const std::int32_t count = round.row_counts[row];
+        if (count <= 0 || count > static_cast<std::int32_t>(round.row_stride)) {
+            throw std::runtime_error("Qwen DFlash2 benchmark returned an invalid row extent");
+        }
+        accepted[row] = static_cast<std::uint32_t>(count);
+        licensed += accepted[row];
+    }
+    program.resolve_pending_batch(lane_span,
+                                  std::span<const std::uint32_t>(accepted.data(), batch_size),
+                                  std::span<const std::uint8_t>(terminal.data(), batch_size),
+                                  std::span<const std::uint8_t>(cancelled.data(), batch_size));
+
+    const float gpu_ms = timer.stop_ms();
+    const double wall_ms =
+        std::chrono::duration<double, std::milli>(Clock::now() - wall_start).count();
+    return {.gpu_ms = gpu_ms, .wall_ms = wall_ms, .licensed_tokens = licensed};
+}
+
+template <class T>
+double mean(const std::vector<T>& values) {
+    return std::accumulate(values.begin(), values.end(), 0.0) /
+           static_cast<double>(values.size());
+}
+
+int run(const Options& options) {
+    if (!std::filesystem::exists(options.artifact)) {
+        std::cout << "SKIP: artifact not present: " << options.artifact.string() << '\n';
+        return 0;
+    }
+    const std::vector<ginfer::TokenId> corpus = load_corpus(options.corpus);
+
+    ginfer::EngineOptions engine;
+    engine.artifact_path              = options.artifact;
+    engine.device                     = options.device;
+    engine.max_context                = kNativeContext;
+    engine.kv_capacity                = ginfer::KvCapacityPolicy::explicit_capacity(kNativeContext);
+    engine.prefill_chunk              = 1024;
+    engine.kv_cache                   = ginfer::KvCacheStorage::Int8Group64;
+    engine.speculative.backend        = ginfer::SpeculativeBackend::DFlash;
+    engine.speculative.draft_tokens   = kDraftTokens;
+    engine.speculative.proposal_head  = ginfer::ProposalHead::Full;
+    engine.use_cuda_graph             = options.use_cuda_graph;
+    engine.max_concurrency            = options.batch_size;
+
+    ginfer::DeviceContext device(options.device);
+    ginfer::artifact::Reader reader(options.artifact);
+    const auto weights_profile = target::Package::resolve_weights(reader.identity());
+    if (weights_profile != target::Package::WeightsProfile::Qwen38Nvfp4DFlash2Q4) {
+        throw std::invalid_argument(
+            "benchmark requires the registered qwen3.8-27b/nvfp4-dflash2-q4 artifact");
+    }
+    ginfer::artifact::Binder binder(reader);
+    auto load_plan        = target::Package::plan_load(binder, engine, weights_profile);
+    auto planner          = target::Package::make_sequence_planner(device, engine, weights_profile);
+    const auto resolution = ginfer::runtime::resolve_kv_capacity(
+        engine.kv_capacity, planner.capacity_curve(), std::numeric_limits<std::size_t>::max());
+    auto sequence = std::move(planner).finalize(resolution.main_page_groups);
+
+    const std::uint64_t weight_bytes   = load_plan.materialization().device_capacity_bytes;
+    const std::uint64_t sequence_bytes = sequence.device_reservation_bytes();
+    if (sequence_bytes > std::numeric_limits<std::uint64_t>::max() - weight_bytes) {
+        throw std::overflow_error("benchmark device-memory requirement overflows uint64");
+    }
+    const std::uint64_t required_bytes = weight_bytes + sequence_bytes;
+    std::size_t free_bytes             = 0;
+    std::size_t total_bytes            = 0;
+    CUDA_CHECK(cudaMemGetInfo(&free_bytes, &total_bytes));
+    if (required_bytes > free_bytes) {
+        throw std::invalid_argument(
+            "benchmark configuration requires " + std::to_string(required_bytes) +
+            " bytes of device memory, but only " + std::to_string(free_bytes) + " bytes are free");
+    }
+
+    auto materialized =
+        ginfer::artifact::materialize(reader, load_plan.materialization(), device, nullptr);
+    auto model =
+        target::Package::construct_loaded_model(std::move(load_plan), std::move(materialized));
+    auto frontend                      = target::Package::make_frontend(*model, engine);
+    const std::size_t request_capacity = sequence.request_transient_capacity_bytes();
+    auto program = target::Package::create_program(*model, std::move(sequence), device);
+    ginfer::runtime::RequestMemory request_memory(device, request_capacity);
+
+    const std::uint32_t measured_rounds =
+        static_cast<std::uint32_t>(options.warmup + options.repetitions);
+    ginfer::runtime::ResolvedExecutionOptions execution;
+    execution.sampling = {.temperature       = 0.7F,
+                          .top_k             = 20,
+                          .top_p             = 0.8F,
+                          .min_p             = 0.0F,
+                          .presence_penalty  = 1.5F,
+                          .frequency_penalty = 0.0F,
+                          .seed              = 42};
+    execution.requested_output_tokens = 1 + measured_rounds * kMaximumRoundOutputs;
+    execution.allow_prefix_reuse      = false;
+
+    for (std::uint32_t lane = 0; lane < options.batch_size; ++lane) {
+        auto prompt = frontend.prepare_tokens(
+            prompt_tokens(corpus, options.context_tokens, lane), false);
+        auto request_base = program->plan_request_base(prompt, execution);
+        auto request_plan = program->plan_request_for_lane(lane, prompt, request_base);
+        request_memory.activate(request_plan.summary().transient_bytes,
+                                request_plan.summary().transient_alignment);
+        auto prefill = program->start_prefill_lane(lane, std::move(prompt), std::move(request_plan),
+                                                   request_memory.region());
+        while (!prefill.complete) { prefill = program->advance_prefill_lane(lane); }
+        request_memory.deactivate();
+        if (prefill.round.tokens.size() != 1) {
+            throw std::runtime_error("Qwen DFlash2 benchmark prefill did not license one token");
+        }
+        program->resolve_prefill_lane(lane, false);
+    }
+
+    for (int iteration = 0; iteration < options.warmup; ++iteration) {
+        (void)measure_round(*program, device, options.batch_size);
+    }
+    std::vector<ginfer::SpeculativeStats> before;
+    before.reserve(options.batch_size);
+    for (std::uint32_t lane = 0; lane < options.batch_size; ++lane) {
+        before.push_back(program->speculative_stats_lane(lane));
+    }
+
+    std::vector<RoundMeasurement> measurements;
+    measurements.reserve(static_cast<std::size_t>(options.repetitions));
+    if (options.profile_measured) { CUDA_CHECK(cudaProfilerStart()); }
+    for (int iteration = 0; iteration < options.repetitions; ++iteration) {
+        measurements.push_back(measure_round(*program, device, options.batch_size));
+    }
+    if (options.profile_measured) { CUDA_CHECK(cudaProfilerStop()); }
+
+    std::vector<float> gpu_ms;
+    std::vector<double> wall_ms;
+    std::uint64_t licensed_tokens = 0;
+    for (const RoundMeasurement& measurement : measurements) {
+        gpu_ms.push_back(measurement.gpu_ms);
+        wall_ms.push_back(measurement.wall_ms);
+        licensed_tokens += measurement.licensed_tokens;
+    }
+    const auto [gpu_min, gpu_max] = std::minmax_element(gpu_ms.begin(), gpu_ms.end());
+
+    std::uint64_t accepted       = 0;
+    std::uint64_t drafted        = 0;
+    std::uint64_t expanded       = 0;
+    std::uint64_t fallback_steps = 0;
+    std::array<std::uint64_t, kVerificationTokens> accepted_per_position{};
+    for (std::uint32_t lane = 0; lane < options.batch_size; ++lane) {
+        const ginfer::SpeculativeStats after = program->speculative_stats_lane(lane);
+        if (after.backend != ginfer::SpeculativeBackend::DFlash || !after.enabled ||
+            after.draft_window != kDraftTokens ||
+            after.verification_window != kVerificationTokens ||
+            after.rounds - before[lane].rounds !=
+                static_cast<std::uint64_t>(options.repetitions)) {
+            throw std::runtime_error("benchmark left the complete learned DFlash2 round path");
+        }
+        accepted += after.accepted_tokens - before[lane].accepted_tokens;
+        drafted += after.drafted_tokens - before[lane].drafted_tokens;
+        expanded += after.expanded_rounds - before[lane].expanded_rounds;
+        fallback_steps += after.fallback_steps - before[lane].fallback_steps;
+        for (std::size_t position = 0; position < accepted_per_position.size(); ++position) {
+            accepted_per_position[position] += after.accepted_per_position[position] -
+                                               before[lane].accepted_per_position[position];
+        }
+    }
+    if (fallback_steps != 0) {
+        throw std::runtime_error("benchmark unexpectedly entered a non-speculative fallback step");
+    }
+
+    const double mean_gpu_ms  = mean(gpu_ms);
+    const double mean_wall_ms = mean(wall_ms);
+    const double mean_licensed_per_batch =
+        static_cast<double>(licensed_tokens) / static_cast<double>(options.repetitions);
+
+    std::cout << "format,ginfer_qwen3_8_27b_dflash2_round_bench_v1\n";
+    std::cout << "artifact," << options.artifact.string() << '\n';
+    std::cout << "device," << device.props.name << '\n';
+    std::cout << "context_tokens," << options.context_tokens << '\n';
+    std::cout << "draft_tokens," << kDraftTokens << '\n';
+    std::cout << "verification_tokens," << kVerificationTokens << '\n';
+    std::cout << "batch_size," << options.batch_size << '\n';
+    std::cout << "kv_cache,int8-group64\n";
+    std::cout << "max_context," << kNativeContext << '\n';
+    std::cout << "kv_capacity," << kNativeContext << '\n';
+    std::cout << "proposal_head,full\n";
+    std::cout << "sampling,stochastic\n";
+    std::cout << "cuda_graph," << (options.use_cuda_graph ? "true" : "false") << '\n';
+    std::cout << "warmup," << options.warmup << '\n';
+    std::cout << "repetitions," << options.repetitions << '\n';
+    std::cout << "steady_round_gpu_mean_ms," << mean_gpu_ms << '\n';
+    std::cout << "steady_round_gpu_min_ms," << *gpu_min << '\n';
+    std::cout << "steady_round_gpu_max_ms," << *gpu_max << '\n';
+    std::cout << "steady_round_wall_mean_ms," << mean_wall_ms << '\n';
+    std::cout << "mean_licensed_tokens_per_batch," << mean_licensed_per_batch << '\n';
+    std::cout << "mean_licensed_tokens_per_request,"
+              << mean_licensed_per_batch / static_cast<double>(options.batch_size) << '\n';
+    std::cout << "drafted_tokens," << drafted << '\n';
+    std::cout << "accepted_draft_tokens," << accepted << '\n';
+    std::cout << "acceptance_rate,"
+              << (drafted == 0 ? 0.0 : static_cast<double>(accepted) / drafted) << '\n';
+    std::cout << "expanded_rounds," << expanded << '\n';
+    std::cout << "published_tokens_per_second,"
+              << 1000.0 * mean_licensed_per_batch / mean_wall_ms << '\n';
+    std::cout << "accepted_per_position";
+    for (const std::uint64_t count : accepted_per_position) { std::cout << ',' << count; }
+    std::cout << '\n';
+    return 0;
+}
+
+} // namespace
+
+int main(int argc, char** argv) {
+    try {
+        return run(parse_options(argc, argv));
+    } catch (const std::exception& error) {
+        std::cerr << "ginfer_qwen3_8_27b_dflash2_round_bench: " << error.what() << '\n';
+        return 1;
+    }
+}

diff --git a/src/ops/linear/q4/q4_dispatch.cpp b/src/ops/linear/q4/q4_dispatch.cpp
index ac1b7afe..a9290668 100644
--- a/src/ops/linear/q4/q4_dispatch.cpp
+++ b/src/ops/linear/q4/q4_dispatch.cpp
@@ -29,6 +29,10 @@ Q4Launch select_closed_q4_mma_launch(std::int32_t n, std::int32_t t) {
     return launch_q4_mma_r64_c128;
 }

+Q4Launch select_qwen_dflash_q4_mma_launch(std::int32_t t) {
+    return t <= 32 ? launch_q4_mma_r64_c32 : launch_q4_mma_r64_c128;
+}
+
